from content.authoring import E, J, L, P, Q, R, T
from content.units.input_text import SCANNER

RETRY = J('Scanner in = new Scanner(System.in);\nwhile (in.hasNextLine()) {\n    String text = in.nextLine().trim();\n    if (text.equals("q")) { System.out.println("Bye"); break; }\n    try {\n        int count = Integer.parseInt(text);\n        if (count < 0 || count > 1000) { System.out.println("Invalid"); continue; }\n        System.out.println("Accepted: " + count);\n        break;\n    } catch (NumberFormatException error) {\n        System.out.println("Invalid");\n    }\n}', SCANNER)
ACCUMULATE = J('Scanner in = new Scanner(System.in);\nint n = in.nextInt();\nlong sum = 0;\nfor (int i = 0; i < n; i++) {\n    sum += in.nextInt();\n}\nSystem.out.println("Sum: " + sum);', SCANNER)
DO_MENU = J('Scanner in = new Scanner(System.in);\nString option;\ndo {\n    if (!in.hasNextLine()) break;\n    option = in.nextLine().trim();\n    switch (option) {\n        case "1": System.out.println("Hello"); break;\n        case "0": System.out.println("Bye"); break;\n        default: System.out.println("Unknown");\n    }\n} while (!option.equals("0"));', SCANNER)
TICKET = J('Scanner in = new Scanner(System.in);\nint unitPrice = 120;\nwhile (in.hasNextLine()) {\n    String text = in.nextLine().trim();\n    if (text.equals("q")) { System.out.println("Bye"); break; }\n    try {\n        int count = Integer.parseInt(text);\n        if (count < 1 || count > 1000) {\n            System.out.println("Invalid count");\n        } else {\n            System.out.println("Total: " + (count * unitPrice));\n        }\n    } catch (NumberFormatException error) {\n        System.out.println("Invalid count");\n    }\n}', SCANNER)

LESSONS = [
L('iteration-loops', 'Repeat with a Counted Loop', 'Trace initialization, condition, body and update.',
  ['A for loop has three control parts: initialization happens once, the condition is checked before each body, and the update runs after each completed body. If the first condition is false, the body never executes.',
   'For zero-based positions, for (int i = 0; i < n; i++) executes n times when n is nonnegative. Using <= n would add an extra iteration. For displayed numbers 1 through n, start at 1 and test <= n instead.',
   'A loop needs progress toward termination. Record the counter at each condition check. Counted loops suit a known number of repetitions; while will suit retrying until an input rule is satisfied.'],
  ['Trace the condition before each iteration.', 'Choose a boundary that produces exactly the intended repetitions.'],
  E(J('for (int i = 0; i < 3; i++) {\n    System.out.println(i);\n}'), '0\n1\n2\n', ['i begins at 0.', '0, 1 and 2 satisfy i < 3.', 'At 3 the condition fails before the next print.']),
  Q('Write all output lines.', J('for (int i = 1; i <= 2; i++) { System.out.println(i); }'), '1\n2', 'The inclusive condition admits 1 and 2, then rejects 3.'),
  R('Explain why i < n from i = 0 runs n times, and what changes with i <= n.', 'The included positions are 0 through n - 1, which gives n iterations. Including n adds one more.', ['I name the first and last included counter values.', 'I explain the zero-iteration case n = 0.']),
  P('Read a valid integer n from 0 through 5. Print the integers 1 through n, one per line. For n = 0 print no output.', J('Scanner in = new Scanner(System.in);\nint n = in.nextInt();\nfor (int i = 1; i <= n; i++) { System.out.println(i); }', SCANNER), [T('three iterations', '3\n', '1\n2\n3\n'), T('zero iterations', '0\n', ''), T('one iteration', '1\n', '1\n')], starter=J('Scanner in = new Scanner(System.in);\nint n = in.nextInt();\n// Print exactly n lines, beginning with 1.', SCANNER)),
  extra_practice=P('Repair the off-by-one loop. Print 0 through n - 1 for a valid nonnegative n.', J('Scanner in = new Scanner(System.in);\nint n = in.nextInt();\nfor (int i = 0; i < n; i++) System.out.println(i);', SCANNER), [T('n two', '2\n', '0\n1\n'), T('empty boundary', '0\n', '')], starter=J('Scanner in = new Scanner(System.in);\nint n = in.nextInt();\nfor (int i = 0; i <= n; i++) System.out.println(i);', SCANNER), kind='repair'),
  diagram={'kind':'loop','nodes':['Initialize i = 0','Check i < n','True: execute body','Update i++','False: exit'],'edges':[[0,1],[1,2],[2,3],[3,1],[1,4]]}),
L('while-retry', 'Retry Invalid Input & Stop Intentionally', 'Continue after a bad line without getting stuck on the same token.',
  ['A while loop checks its condition before each body. A retry loop usually consumes one whole line every iteration. If parsing fails, that line has already been consumed, so the next iteration sees new input rather than repeating the same bad token forever.',
   'continue skips the rest of the current iteration and checks the loop condition again. break exits the nearest enclosing loop. In the example, an invalid count retries; a valid count or q ends the loop.',
   'hasNextLine distinguishes another supplied line from end-of-input. EOF must also terminate the program. The Studio supplies a finite input batch, so a missing q must not create a busy loop.'],
  ['Consume invalid input before retrying.', 'Distinguish retry, intentional exit and EOF.'],
  E(RETRY, 'Invalid\nAccepted: 4\n', ['pear fails conversion and is consumed.', 'The next line converts successfully.', 'Accepted work exits the loop.'], 'pear\n4\n'),
  Q('For input -1 then q, write the exact output lines.', RETRY, 'Invalid\nBye', 'The negative count retries with continue; q takes the deliberate exit path.'),
  R('What causes a retry loop to get stuck on invalid input, and how does whole-line input avoid it?', 'Checking the same token without consuming it leaves the failing input in place. Reading a whole line before conversion guarantees progress; hasNextLine handles EOF.', ['I identify input consumption as progress.', 'I handle both quit and EOF termination.']),
  P('Retry whole-line integer input until a value from 1 through 10 is accepted. Print Invalid for bad or out-of-range lines, Accepted: n for the accepted value, Bye for q, and stop quietly at EOF.', J(RETRY.split('    public static void main(String[] args) {\n',1)[1].rsplit('\n    }',1)[0].replace('count < 0 || count > 1000','count < 1 || count > 10'), SCANNER), [T('recover from text', 'pear\n3\n', 'Invalid\nAccepted: 3\n'), T('quit after range error', '0\nq\n', 'Invalid\nBye\n'), T('upper boundary', '10\n', 'Accepted: 10\n'), T('EOF after bad line', 'bad\n', 'Invalid\n'), T('empty batch', '', '')], starter=J('Scanner in = new Scanner(System.in);\n// While a line exists: handle q, parse, range-check, retry or accept.', SCANNER))),
L('loop-accumulation', 'Count & Accumulate', 'Keep per-iteration input separate from the running result.',
  ['Initialize an accumulator once before the loop. Update it inside the loop. Reinitializing it inside the body loses previous values. A counter and an accumulator have different roles even when both are numbers.',
   'This exercise’s input contract supplies a nonnegative n followed by exactly n valid int values. A long accumulator gives more range than int for the sum. Robust conversion for arbitrary text is already covered separately; do not confuse a stated valid-input exercise with a general parser.',
   'Test n = 0, one element, and a mix of positive and negative values. For an average, a zero count needs its own guard; never divide an empty accumulator by zero.'],
  ['Initialize and update a running sum correctly.', 'Show what a loop does for an empty input group.'],
  E(ACCUMULATE, 'Sum: 9\n', ['Read n = 3.', 'Start sum at 0.', 'Accumulate 2, 3 and 4.', 'Print after the loop.'], '3 2 3 4\n'),
  Q('For input 3 5 -2 0, what exact output line is printed?', ACCUMULATE, 'Sum: 3', 'The sum preserves the first value and adds each later value, including negatives and zero.'),
  R('Where must a running total be initialized, and what should its result be for zero items?', 'Initialize once before the loop. With zero items the body does not run and the total remains its initial zero.', ['I keep initialization outside the repeated body.', 'I trace the zero-item boundary.']),
  P('Read valid n from 0 through 20 followed by n valid int values. Print Sum: followed by their long sum. Do not reset the accumulator inside the loop.', ACCUMULATE, [T('mixed values', '3 8 -3 2\n', 'Sum: 7\n'), T('empty group', '0\n', 'Sum: 0\n'), T('sum exceeds int', '2 2000000000 2000000000\n', 'Sum: 4000000000\n')], starter=J('Scanner in = new Scanner(System.in);\nint n = in.nextInt();\nlong sum = 0;\n// Read and accumulate exactly n values.\nSystem.out.println("Sum: " + sum);', SCANNER))),
L('do-while-menu', 'A Menu That Can Repeat', 'Use a post-test loop without confusing switch break with loop exit.',
  ['A do/while executes its body before checking the loop condition, so the body runs at least once. The example still checks hasNextLine inside the body before reading. Its final semicolon belongs to the do/while statement.',
   'A break inside a switch ends that switch, not an outer loop. To stop this menu, the selected command also controls the loop condition. A different design can use a running boolean. Make exit state explicit.',
   'Unknown commands should produce a useful message and return to the menu. EOF must stop even when no exit command appears. Do not print a success result for an invalid choice.'],
  ['Trace a post-test loop and its termination.', 'Distinguish a switch break from exiting the surrounding menu.'],
  E(DO_MENU, 'Hello\nUnknown\nBye\n', ['1 routes to Hello.', 'The loop repeats for an unknown command.', '0 prints Bye and makes the loop condition false.'], '1\nx\n0\n'),
  Q('For input 1 then 1 then 0, how many Hello lines are printed? Write the count.', DO_MENU, '2', 'Each 1 executes one menu iteration; 0 exits after its own branch.'),
  R('Why does break in case "1" not terminate this whole menu?', 'Its nearest breakable construct is the switch. The outer do/while repeats unless its condition becomes false or a separate loop exit is taken.', ['I identify the construct exited by break.', 'I describe the actual menu exit condition.']),
  P('Build a repeated do/while command menu: h → Hello, q → Bye and exit, anything else → Unknown. Stop quietly at EOF.', J('Scanner in = new Scanner(System.in);\nString choice;\ndo {\n    if (!in.hasNextLine()) break;\n    choice = in.nextLine().trim();\n    switch (choice) {\n        case "h": System.out.println("Hello"); break;\n        case "q": System.out.println("Bye"); break;\n        default: System.out.println("Unknown");\n    }\n} while (!choice.equals("q"));', SCANNER), [T('repeat and exit', 'h\nh\nq\n', 'Hello\nHello\nBye\n'), T('recover unknown', 'x\nh\nq\n', 'Unknown\nHello\nBye\n'), T('EOF', '', '')], starter=J('Scanner in = new Scanner(System.in);\n// Use do/while. Guard EOF before reading, dispatch, and stop on q.', SCANNER))),
L('workflow-projects', 'Milestone: a Resilient Ticket Counter', 'Integrate input, guards, repetition and output into one usable program.',
  ['The first practical milestone accepts one ticket count per line, computes a total for each valid request, and repeats until q or EOF. The unit price is 120. Counts are whole numbers from 1 through 1000, keeping the bounded int multiplication safe.',
   'Separate conversion failures from range failures in your reasoning, even when the required user message is the same. A rejected request must not produce a total or terminate future valid requests. Use whole-line reads so no invalid token is left behind.',
   'Plan a test table before implementation: normal count, smallest count, zero, negative, trailing junk, overflow, valid request after an error, quit and EOF. Passing only one convenient request is not enough. This version is intentionally one main method; the next stage refactors it.'],
  ['Build a repeated console workflow from a requirement.', 'Demonstrate recovery, boundaries and deliberate termination.'],
  E(TICKET, 'Invalid count\nTotal: 240\nBye\n', ['Bad text is rejected.', 'The following valid count still works.', 'q terminates without another total.'], 'oops\n2\nq\n'),
  Q('Input is 0 then 1 then q. Write all output lines.', TICKET, 'Invalid count\nTotal: 120\nBye', 'Zero is outside the allowed count range; one ticket costs 120; q ends the loop.'),
  R('Explain the input contract and how you would prove an invalid request does not break the next request.', 'Each line is q or a whole count in 1..1000. Supply a bad line followed by a valid count and q; expect an invalid message, the valid total and Bye.', ['I state the count range and exit command.', 'I test recovery with a later valid line.', 'I include EOF and a boundary.']),
  P('Write the ticket counter independently: price 120, counts 1..1000, one request per line. Print Total: n for valid requests, Invalid count for bad/out-of-range input, Bye for q. Repeat after invalid requests, stop quietly at EOF.', TICKET, [T('normal and minimum', '3\n1\nq\n', 'Total: 360\nTotal: 120\nBye\n'), T('recover and quit', 'bad\n0\n-2\n2\nq\n', 'Invalid count\nInvalid count\nInvalid count\nTotal: 240\nBye\n'), T('maximum and above', '1000\n1001\nq\n', 'Total: 120000\nInvalid count\nBye\n'), T('overflow and EOF', '99999999999999999\n4\n', 'Invalid count\nTotal: 480\n')], hints=['Write the input→conversion→range→total plan first.', 'Use one whole-line read per iteration; handle q before parsing.'], rubric=['I can explain how each invalid line is consumed.', 'I bounded the count before multiplication.', 'I can change the unit price without rewriting the output cases.']),
  extra_practice=P('Transfer: modify the workflow into a parcel counter. Price is 80 per parcel; accept 1..100 parcels. Keep Invalid count, Total: n and Bye messages.', J(TICKET.split('    public static void main(String[] args) {\n',1)[1].rsplit('\n    }',1)[0].replace('unitPrice = 120','unitPrice = 80').replace('count > 1000','count > 100'), SCANNER), [T('parcel price', '2\nq\n', 'Total: 160\nBye\n'), T('parcel boundary', '100\n101\nq\n', 'Total: 8000\nInvalid count\nBye\n')], starter=TICKET, kind='modify')),
]
